          "body": "**Infrastructure:**\n- 500 solar panels (250 kW installed capacity)\n- 2 wind micro-turbines (20 kW total)\n- Geothermal system for heating and cooling\n- Battery storage (48-hour autonomy)\n- Biogas plant from composting waste\n- ZION node for managing the energy network via smart contracts"
