          "body": "```\n 1.  Thoughts are not mine\n 2.  The mind is not mine\n 3.  This body is not mine\n 4.  All things happen automatically\n 5.  There is thinking, but no thinker\n 6.  There is seeing, but no observer\n 7.  There is hearing, but no listener\n 8.  There is doing, but no doer\n 9.  Inside there is no person — Nobody is in there\n10.  I Am Being, Consciousness, Bliss\n11.  I am Love\n12.  The whole world is family\n```"
